<?php $page_title='Dashboard Mahasiswa';require_once __DIR__.'/../includes/header.php';require_login(['mahasiswa']);$pdo=db();$mid=student_id();$ta=$pdo->query("SELECT id FROM tahun_akademik WHERE status='Aktif' LIMIT 1")->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(mk.sks),0) sks,COUNT(*) mk,COALESCE(SUM(mk.sks*n.bobot)/NULLIF(SUM(mk.sks),0),0) ip FROM krs k JOIN mata_kuliah mk ON mk.id=k.id_mk LEFT JOIN nilai n ON n.id_krs=k.id WHERE k.id_mahasiswa=? AND k.id_tahun_akademik=?');$q->execute([$mid,$ta]);$term=$q->fetch();$q=$pdo->prepare('SELECT COALESCE(SUM(mk.sks*n.bobot)/NULLIF(SUM(mk.sks),0),0) ipk FROM krs k JOIN mata_kuliah mk ON mk.id=k.id_mk JOIN nilai n ON n.id_krs=k.id WHERE k.id_mahasiswa=?');$q->execute([$mid]);$ipk=$q->fetchColumn();?><h3 class="mb-4">Dashboard Mahasiswa</h3><div class="row g-3"><?php foreach([['Jumlah SKS',$term['sks'],'bi-journal-check'],['IP Semester',number($term['ip']),'bi-graph-up-arrow'],['IPK',number($ipk),'bi-award'],['Mata Kuliah',$term['mk'],'bi-book']] as [$n,$v,$i]):?><div class="col-md-3"><div class="card p-4"><i class="bi <?=$i?> text-primary fs-3"></i><div class="text-secondary mt-2"><?=$n?></div><div class="display-6 fw-bold"><?=$v?></div></div></div><?php endforeach?></div><?php require_once __DIR__.'/../includes/footer.php';?>
